E = [
 # --- miary demograficzne ---
 ("Demografia", "Nauka o ludności: jej liczbie, rozmieszczeniu, strukturze (wiek, płeć, stan cywilny, wykształcenie) i zmianach wynikających z ruchu naturalnego (urodzenia, zgony, małżeństwa, rozwody) i wędrówkowego (migracje). Źródła danych: spisy powszechne (NSP 2021), bieżąca rejestracja, badania reprezentacyjne.", {"p": "Gdy gmina planuje, ile miejsc w przedszkolach będzie potrzebnych za 5 lat, liczy dzieci już urodzone i spodziewane urodzenia – to demografia w praktyce.", "k": ["demograf", "ruch naturaln", "ruch wędrówkow", "spis powszechn", "nsp"]}),
 ("Współczynnik dzietności (TFR)", "Przeciętna liczba dzieci urodzonych przez kobietę w ciągu życia przy płodności z danego roku; suma cząstkowych współczynników płodności dla wieku 15–49 lat.", {"p": "TFR = 1,1 znaczy: gdyby kobiety przez całe życie rodziły tak jak w tym roku, przeciętnie miałyby 1,1 dziecka. Para „zastępuje się” dopiero przy ok. 2 dzieciach.", "w": "TFR = Σ fₓ (fₓ – urodzenia kobiet w wieku x / liczba kobiet w wieku x); dla grup 5-letnich: TFR = 5 · Σ f₅ₓ", "u": "Polska: 1,07 (2025), UE: 1,34 (2024) – najniższe w UE Malta 1,01 (2024).", "k": ["dzietnoś", "tfr", "płodnoś"]}),
 ("Zastępowalność pokoleń", "Poziom dzietności zapewniający długookresowo stałą liczbę ludności bez migracji – ok. 2,1 dziecka na kobietę (nadwyżka ponad 2 rekompensuje przewagę urodzeń chłopców i zgony przed wiekiem rozrodczym). Współczynnik reprodukcji netto (NRR) = 1 oznacza dokładną zastępowalność; w Polsce dzietność jest poniżej progu od 1989 r. Współczynnik reprodukcji brutto (GRR) to przeciętna liczba córek urodzonych przez kobietę przy obecnej płodności, bez uwzględnienia umieralności (GRR ≈ TFR × udział dziewczynek wśród urodzeń, ok. 0,486); NRR uwzględnia też zgony kobiet przed końcem wieku rozrodczego.", {"p": "Dwoje rodziców musi „zostawić” średnio dwoje dorosłych dzieci. Ponieważ część dzieci umiera przed dorosłością, a chłopców rodzi się trochę więcej, potrzeba ok. 2,1 urodzenia na kobietę.", "w": "NRR = liczba córek dożywających wieku matki, przypadająca na 1 kobietę; NRR < 1 – zawężona reprodukcja", "k": ["zastępowalnoś", "reprodukcj", "nrr", "grr", "współczynnik reprodukcji brutto", "współczynnik reprodukcji netto"]}),
 ("Współczynniki urodzeń, zgonów i przyrostu naturalnego", "Współczynniki surowe – liczba zdarzeń na 1000 mieszkańców w roku. Przyrost naturalny = urodzenia żywe − zgony; przyrost rzeczywisty = przyrost naturalny + saldo migracji. Umieralność niemowląt – zgony dzieci w 1. roku życia na 1000 urodzeń żywych (miara poziomu rozwoju i opieki zdrowotnej).", {"w": "PN‰ = (U − Z) / L · 1000;  przyrost rzeczywisty = (U − Z) + (I − E)", "p": "U = 238 tys., Z = 406 tys., L = 37,4 mln ⇒ PN ≈ −4,5‰.", "k": ["przyrost naturaln", "przyrostu naturaln", "umieralnoś niemowląt", "współczynnik urodzeń", "współczynnik zgonów", "przyrost rzeczywist"]}),
 ("Saldo migracji", "Różnica między liczbą imigrantów (napływ) a emigrantów (odpływ) w danym okresie; saldo dodatnie – kraj imigracyjny, ujemne – emigracyjny. Wskaźnik na 1000 ludności – współczynnik salda migracji.", {"p": "Do miasta przyjechało w roku 12 tys. osób, a wyjechało 9 tys. – saldo migracji wynosi +3 tys., więc miasto „zyskało” mieszkańców mimo ewentualnego ubytku naturalnego.", "w": "SM = I − E;  współczynnik = (I − E) / L · 1000", "k": ["saldo migracji", "salda migracji", "napływ", "odpływ"]}),
 ("Przeciętne dalsze trwanie życia i tablice trwania życia", "Tablice trwania życia (GUS) opisują porządek wymierania hipotetycznej generacji przy umieralności z danego roku; podają m.in. prawdopodobieństwo zgonu i przeciętne dalsze trwanie życia osoby w wieku x (dla x = 0 – oczekiwana długość życia noworodka). Tablice dla obu płci łącznie służą ZUS do obliczania emerytury.", {"p": "Gdy GUS podaje, że 60-latek przeżyje jeszcze średnio ok. 22 lata, ZUS dzieli zgromadzony kapitał przez liczbę miesięcy z tej tablicy – dłuższe życie oznacza niższą miesięczną emeryturę.", "u": "2025: noworodek – mężczyźni 75,4 lat, kobiety 82,5 lat; 60-latek – mężczyźni 20,0, kobiety 24,7 lat.", "k": ["trwani życia", "trwania życia", "długoś życia", "długość życia", "długości życia", "tablic trwania"]}),
 ("Struktura wieku: wiek przedprodukcyjny, produkcyjny i poprodukcyjny", "W statystyce GUS: przedprodukcyjny 0–17 lat, produkcyjny 18–59 lat (kobiety) i 18–64 lata (mężczyźni) – w tym mobilny 18–44 i niemobilny 45–59/64 – poprodukcyjny 60+/65+. W porównaniach międzynarodowych (Eurostat, ONZ): 0–14, 15–64, 65+.", {"p": "Jeśli przybywa osób po 60./65. roku życia, a ubywa w wieku 18–59/64, mniej pracujących musi „utrzymać” więcej emerytów – stąd debata o wieku emerytalnym.", "k": ["wiek produkcyjn", "wieku produkcyjn", "przedprodukcyjn", "poprodukcyjn", "struktur wieku", "struktura wieku"]}),
 ("Współczynnik obciążenia demograficznego", "Liczba osób w wieku nieprodukcyjnym przypadająca na 100 osób w wieku produkcyjnym; wyróżnia się obciążenie młodzieżą i osobami starszymi. Wskaźnik wsparcia potencjalnego to jego odwrotność dla seniorów (ile osób w wieku produkcyjnym przypada na jednego seniora).", {"w": "WO = (L₀₋₁₄ + L₆₅₊) / L₁₅₋₆₄ · 100;  obciążenie starszymi = L₆₅₊ / L₁₅₋₆₄ · 100", "p": "UE 1.01.2024: obciążenie starszymi 33,9% ⇒ ok. 3 osoby w wieku 15–64 na 1 osobę 65+.", "k": ["obciążeni demograficzn", "współczynnik obciążenia", "wskaźnik obciążenia", "wsparci potencjaln"]}),
 ("Starzenie się ludności i jego miary", "Wzrost udziału osób starszych w populacji wskutek spadku dzietności (starzenie się „od dołu” piramidy) i wydłużania życia (starzenie się „od góry”). Miary: współczynnik starości (odsetek osób 65+; populacja „stara” powyżej 7%, wg ONZ), indeks starości (osoby 65+ na 100 dzieci 0–14), mediana wieku, podwójne starzenie się (szybki wzrost liczby osób 80+).", {"p": "Polska się starzeje z dwóch stron jednocześnie: rodzi się mniej dzieci (podstawa piramidy się zwęża) i ludzie żyją dłużej (wierzchołek się poszerza).", "w": "współczynnik starości = L₆₅₊ / L · 100;  indeks starości = L₆₅₊ / L₀₋₁₄ · 100", "u": "Mediana wieku w Polsce ok. 43 lata (2024), w 2060 r. wg prognozy GUS ok. 50 lat; odsetek 65+ w UE 21,6% (2024).", "k": ["starzeni", "starości", "mediana wieku", "mediany wieku", "podwójne starzen"]}),
 ("Piramida wieku", "Wykres struktury ludności według wieku i płci (mężczyźni po lewej, kobiety po prawej). Kształty: progresywny (trójkąt – wysoka dzietność), stacjonarny (dzwon), regresywny (urna, odwrócona podstawa – starzejące się społeczeństwa, np. Polska, Japonia). Na polskiej piramidzie widać wyże powojenny (lata 50.) i jego echo (początek lat 80.) oraz niże.", {"p": "Piramida Nigru wygląda jak trójkąt (dużo dzieci), Japonii – jak urna (najwięcej osób w średnim i starszym wieku). Polska piramida ma „wcięcia” po II wojnie i w latach 90.", "k": ["piramid"]}),
 ("Wyż i niż demograficzny, echo wyżu", "Wyż – okres wyraźnie większej liczby urodzeń (w Polsce 1946–1960, szczyt ok. 793 tys. urodzeń w 1955 r.; wyż echa 1976–1985); niż – mniejszej (lata 90. i 2000.). Echo wyżu – ponowny wzrost urodzeń, gdy liczne roczniki wchodzą w wiek rodzicielski. Fale wyżów i niżów przesuwają się przez szkoły, rynek pracy i system emerytalny.", {"p": "Liczni urodzeni w latach 50. mieli w latach 80. własne dzieci – stąd drugi szczyt urodzeń (echo). Gdy dzieci echa weszły w wiek rodzicielski po 2010 r., trzeci szczyt był już słaby.", "k": ["wyż demograficzn", "niż demograficzn", "echo wyżu", "wyżu demograficzn", "niżu demograficzn"]}),
 ("Prognoza ludności GUS", "Projekcja liczby i struktury ludności według założeń o dzietności, umieralności i migracjach. Prognoza z 2024 r.: spadek ludności Polski do ok. 30,9 mln w 2060 r. (o ok. 6,6 mln wobec 2024 r.), ok. 225 tys. urodzeń i blisko 490 tys. zgonów rocznie w 2060 r., mediana wieku ok. 50 lat.", {"p": "Prognoza to „co będzie, jeśli” – np. jeśli dzietność utrzyma się ok. 1,3, a saldo migracji będzie niewielkie, w 2060 r. Polskę zamieszka ok. 31 mln osób. Inne założenia dają inny wynik.", "u": "prognozy to warianty warunkowe, nie pewne przewidywania", "k": ["prognoz ludnoś", "prognoza ludności", "prognozy ludności", "2060"]}),
 ("Depopulacja", "Trwały spadek liczby ludności kraju lub regionu wskutek ujemnego przyrostu naturalnego i/lub odpływu migracyjnego. W Polsce ludność maleje od 2012 r.; najszybciej wyludniają się regiony peryferyjne i małe miasta (np. woj. opolskie, świętokrzyskie, łódzkie), a rosną strefy podmiejskie dużych aglomeracji.", {"p": "W małym mieście po zamknięciu zakładu pracy młodzi wyjeżdżają do metropolii, rodzi się mniej dzieci, szkoły łączą się, a koszt utrzymania wodociągów i dróg na mieszkańca rośnie.", "k": ["depopulac", "wyludni", "spadek liczby ludności", "kurczeni miast", "kurczące się miast"]}),
 ("Urbanizacja i suburbanizacja", "Urbanizacja – wzrost udziału ludności miejskiej i przemiana stylu życia (w Polsce ok. 60% ludności w miastach); suburbanizacja – przenoszenie się mieszkańców z centrów miast do stref podmiejskich; dezurbanizacja – odpływ z dużych miast w ogóle; reurbanizacja – powrót do centrów.", {"p": "Rodzina pracująca w Warszawie kupuje dom w gminie pod miastem – liczba mieszkańców stolicy rośnie wolno, ale podwarszawskie gminy rosną najszybciej w kraju (suburbanizacja).", "k": ["urbaniz", "suburbaniz", "dezurbaniz", "reurbaniz"]}),
 # --- teorie ---
 ("Przejście (transformacja) demograficzne", "Przemiana od reżimu wysokiej rozrodczości i umieralności do niskiej rozrodczości i umieralności, typowa dla modernizacji (F. Notestein 1945, wcześniej W. Thompson, A. Landry). Fazy: 1) wysokie urodzenia i zgony; 2) spadek umieralności przy wysokiej rozrodczości – eksplozja demograficzna; 3) spadek rozrodczości; 4) niski poziom obu – stabilizacja lub spadek liczby ludności. Poprzedza je „sekularna równowaga demograficzna” społeczeństw przedprzemysłowych.", {"p": "W XIX-wiecznej wsi kobieta rodziła 6–7 dzieci, ale połowa umierała w dzieciństwie. Gdy medycyna obniżyła zgony, rodzin wielodzietnych przybyło, a dopiero później rodziny zaczęły świadomie planować mniej dzieci.", "k": ["przejści demograficzn", "przejście demograficzne", "transformacj demograficzn", "transformacja demograficzna", "eksplozj demograficzn", "notestein"]}),
 ("Drugie przejście demograficzne", "Koncepcja D. van de Kaa i R. Lesthaeghe (1986): od lat 60. XX w. w krajach rozwiniętych dzietność spada trwale poniżej zastępowalności wskutek zmian wartości (indywidualizm, samorealizacja), opóźniania małżeństw i rodzicielstwa, wzrostu liczby kohabitacji, rozwodów i urodzeń pozamałżeńskich, upowszechnienia antykoncepcji.", {"p": "Para trzydziestolatków mieszka razem bez ślubu, oboje robią kariery i odkładają decyzję o dziecku „na później” – to typowy obraz drugiego przejścia.", "k": ["drugi przejści", "drugie przejście", "lesthaeghe", "van de kaa", "kohabitac", "pozamałżeńsk"]}),
 ("Przejście epidemiologiczne i przejście migracyjne", "Epidemiologiczne (A. Omran 1971) – zmiana głównych przyczyn zgonów z chorób zakaźnych na przewlekłe i cywilizacyjne (krążenia, nowotwory) wraz z wydłużaniem życia. Migracyjne (W. Zelinsky 1971) – w toku modernizacji kraj przechodzi od emigracji netto do imigracji netto; Polska ma „niedokończone przejście migracyjne” (M. Okólski) – emigracja i imigracja współwystępują.", {"p": "Sto lat temu Polacy umierali głównie na gruźlicę i choroby zakaźne, dziś – na choroby serca i nowotwory. Jednocześnie Polska z kraju emigracji staje się krajem imigracji.", "k": ["epidemiologiczn", "przejści migracyjn", "przejście migracyjne", "zelinsky", "omran"]}),
 ("Przejście struktury wieku", "Zmiana struktury wieku towarzysząca przejściu demograficznemu: najpierw odmłodzenie (spada umieralność dzieci), potem rośnie udział osób w wieku produkcyjnym (okno demograficzne – dywidenda demograficzna, por.), wreszcie szybkie starzenie się, gdy liczne roczniki osiągają wiek poprodukcyjny.", {"p": "Najpierw (wysoka dzietność) społeczeństwo jest młode, potem przez kilkadziesiąt lat dominują osoby w wieku produkcyjnym (okno demograficzne), a na końcu przybywa seniorów.", "k": ["przejści struktury wieku", "przejście struktury wieku", "okno demograficzn"]}),
 ("Druga dywidenda demograficzna", "Korzyść możliwa po wygaśnięciu pierwszej (por. Dywidenda demograficzna): starzejące się społeczeństwo, oszczędzając na starość, gromadzi kapitał, który podnosi produktywność i dochód – pod warunkiem kapitałowego, a nie wyłącznie repartycyjnego finansowania emerytur (R. Lee, A. Mason).", {"p": "Czterdziestolatek wie, że pożyje do 85 lat, więc więcej oszczędza na emeryturę – te oszczędności finansują inwestycje firm i mogą przyspieszać wzrost gospodarczy.", "k": ["drug dywidend", "druga dywidenda"]}),
 ("Pułapka maltuzjańska", "Stan gospodarki przedprzemysłowej, w którym każdy wzrost produkcji żywności zwiększa liczbę ludności, aż dochód na mieszkańca wraca do poziomu minimum egzystencji (por. Malthus Thomas). Przełamała ją rewolucja przemysłowa i przejście demograficzne; neomaltuzjanizm – obawy przed przeludnieniem i wyczerpaniem zasobów (Klub Rzymski, „Granice wzrostu” 1972).", {"p": "W średniowieczu dobry urodzaj dawał więcej żywności, więc rodziło się i przeżywało więcej dzieci – po pokoleniu żywności na osobę było znów tyle samo co wcześniej.", "k": ["maltuzjańsk", "neomaltuzjan", "przeludnieni", "granice wzrostu", "klub rzymski"]}),
 ("Ekonomiczna teoria płodności (G. Becker)", "Dzieci traktowane jak „dobro trwałe”: rodzice wybierają liczbę i „jakość” dzieci (wydatki na edukację, zdrowie) przy ograniczeniu dochodu i czasu. Wzrost płac kobiet podnosi koszt alternatywny wychowania dzieci, a rosnący zwrot z kapitału ludzkiego przesuwa wybór od ilości do jakości – dzietność spada.", {"p": "Gdy wykształcona kobieta zarabia 10 tys. zł miesięcznie, rok urlopu wychowawczego „kosztuje” ją 120 tys. zł utraconych zarobków – im wyższa płaca, tym droższy czas poświęcony dzieciom.", "k": ["teori płodności", "teoria płodności", "ilość i jakość dzieci", "ilości i jakości", "koszt alternatywn dziecka", "becker"]}),
 ("Hipoteza Easterlina (względnego dochodu)", "R. Easterlin: dzietność zależy od dochodu młodych ludzi względem aspiracji wyniesionych z domu; liczne roczniki mają gorszą pozycję na rynku pracy, więc mają mniej dzieci, a nieliczne – więcej (cykliczne fale urodzeń). Easterlin znany jest też z paradoksu szczęścia (wzrost dochodu nie zwiększa trwale szczęścia).", {"p": "Liczne roczniki wyżu z trudem znajdowały pracę i mieszkania, więc w porównaniu z oczekiwaniami czuły się biedniej i miały mniej dzieci – a ich nieliczne dzieci miały łatwiejszy start.", "k": ["easterlin"]}),
 ("Polityka ludnościowa (demograficzna)", "Działania państwa wpływające na liczbę i strukturę ludności: pronatalistyczna (zachęty do posiadania dzieci – świadczenia, ulgi, urlopy, żłobki, mieszkania), antynatalistyczna (np. chińska polityka jednego dziecka 1980–2015), migracyjna, zdrowotna. Skuteczność transferów pieniężnych dla dzietności jest ograniczona – ważniejsze są usługi opiekuńcze, stabilność zatrudnienia i mieszkania. Por. Polityka rodzinna i mieszkaniowa.", {"p": "800+ (pieniądze), żłobki (usługi) i urlopy rodzicielskie (czas) to trzy rodzaje narzędzi tej samej polityki – mogą wspierać zarówno dzietność, jak i pracę rodziców.", "k": ["polityk ludnościow", "polityka ludnościowa", "polityk demograficzn", "polityka demograficzna", "pronatalist", "antynatalist", "jednego dziecka"]}),
 ("Instrumenty polityki rodzinnej w Polsce", "Świadczenie wychowawcze 800+ (por. Świadczenia społeczne), rodzinny kapitał opiekuńczy (od 2022 r.), program „Aktywny rodzic” (od 1 października 2024 r., tzw. babciowe – świadczenie na opiekę nad dzieckiem do 3 lat), becikowe, urlop macierzyński i rodzicielski, ulga podatkowa na dzieci, Karta Dużej Rodziny (od 2014 r.), dopłaty do kredytów mieszkaniowych.", {"p": "Rodzina z dwójką dzieci w wieku 1 i 6 lat może dostać 800+ na każde dziecko, świadczenie „Aktywny rodzic” na młodsze, ulgę w PIT i wyprawkę „Dobry start” na starsze.", "u": "stan na 2026 r.", "k": ["aktywny rodzic", "babciow", "rodzinny kapitał opiekuńcz", "becikow", "karta dużej rodziny", "urlop rodzicielsk", "urlop macierzyńsk"]}),
 ("Regionalna polityka demograficzna", "Działania samorządów województw przeciw depopulacji, np. Specjalna Strefa Demograficzna w woj. opolskim (program od 2014 r. – wsparcie rodzin, rynku pracy i powrotów migrantów), plan przeciwdziałania depopulacji woj. łódzkiego.", {"p": "Województwo traci młodych, więc dopłaca do żłobków, buduje mieszkania na wynajem i zachęca absolwentów do powrotu – to regionalna odpowiedź na depopulację.", "k": ["regionaln polityk demograficzn", "regionalna polityka demograficzna", "specjaln stref demograficzn", "specjalna strefa demograficzna"]}),
 # --- starzenie się a gospodarka ---
 ("Wielki zwrot demograficzny (teza Goodharta i Pradhana)", "Według C. Goodharta i M. Pradhana (2020, wyd. pol. 2024) w latach ok. 1990–2020 wejście Chin i Europy Środkowo-Wschodniej do światowego systemu handlu oraz liczne roczniki w wieku produkcyjnym podwoiły efektywną podaż pracy dla gospodarki światowej – to obniżało płace realne, inflację i stopy procentowe oraz zwiększało nierówności wewnątrz krajów. Teraz trendy się odwracają: kurczą się zasoby pracy, rośnie liczba osób starszych (konsumujących, ale nieprodukujących), więc wzrośnie siła przetargowa pracowników, płace i inflacja, a nierówności zmaleją.", {"p": "Przez 30 lat firmy mogły przenieść produkcję do Chin, gdzie pracowników było „bez końca”. Gdy ta pula się wyczerpie, a Zachód się zestarzeje, pracownicy odzyskają siłę przetargową – a płace i ceny zaczną szybciej rosnąć.", "k": ["zwrot demograficzn", "zwrotu demograficzn", "goodhart", "pradhan", "nadpodaż pracy", "podaży pracy"]}),
 ("Demografia a inflacja i stopy procentowe", "Teza o powrocie inflacji: starzejące się społeczeństwo zmniejsza oszczędności (seniorzy je konsumują – rozszczędzanie), a niedobór pracy skłania firmy do inwestycji w kapitał, więc rośnie naturalna stopa procentowa i presja płacowa; wysoki dług ogranicza chęć banków centralnych do zacieśniania polityki. Kontrargument: przykład Japonii (spadek siły roboczej od 1995 r., ludności od ok. 2008 r., a mimo to deflacja i zerowe stopy przez ok. 25 lat).", {"p": "Pięćdziesięciolatek dużo oszczędza, emeryt wydaje oszczędności. Gdy pokolenie wyżu przechodzi na emeryturę, podaż oszczędności spada – a to może podnosić stopy procentowe.", "k": ["demografi a inflac", "rozszczędzan", "japoni", "japonizac"]}),
 ("Punkt zwrotny Lewisa", "Moment, w którym w gospodarce dualnej (A. Lewis 1954) wyczerpują się nadwyżki taniej siły roboczej z rolnictwa i płace w nowoczesnym sektorze zaczynają szybko rosnąć; wg Goodharta i Pradhana Chiny przekroczyły go w latach 2010., co kończy erę taniej pracy dla świata.", {"p": "Dopóki chiński rolnik mógł przenieść się do fabryki za niewielką płacę, płace w przemyśle rosły wolno. Gdy nadwyżka siły roboczej na wsi się skończyła, płace w fabrykach zaczęły rosnąć szybko.", "k": ["punkt zwrotn lewisa", "lewis", "gospodark dualn", "gospodarka dualna"]}),
 ("Sekularna stagnacja", "Długotrwale niski wzrost gospodarczy przy bardzo niskiej naturalnej stopie procentowej, wynikający m.in. z nadwyżki oszczędności nad inwestycjami; pojęcie A. Hansena (1938 – spowolnienie wzrostu ludności), przywrócone przez L. Summersa (2013). Starzenie się może ją pogłębiać (mniej inwestycji) lub łagodzić (rozszczędzanie seniorów).", {"p": "Starzejące się społeczeństwo dużo oszczędza, a firmy inwestują mało (bo przybywa mniej pracowników) – stopy procentowe muszą spaść bardzo nisko, żeby pobudzić popyt.", "k": ["sekularn stagnac", "sekularna stagnacja", "sekularnej stagnacji", "summers", "hansen"]}),
 ("Srebrna gospodarka", "Działalność gospodarcza odpowiadająca na potrzeby osób starszych (50+, 60+): usługi zdrowotne i opiekuńcze, turystyka, rekreacja, mieszkalnictwo dostosowane do potrzeb seniorów, gerontechnologie, produkty finansowe (np. odwrócona hipoteka); szansa rozwojowa starzejących się społeczeństw.", {"p": "Firma produkuje telefony z dużymi przyciskami i przyciskiem alarmowym, biuro podróży organizuje wycieczki dla seniorów, a bank – doradztwo w planowaniu emerytury: to srebrna gospodarka.", "k": ["srebrn gospodark", "srebrna gospodarka", "srebrnej gospodarki", "gerontechnolog", "odwrócon hipotek"]}),
 ("Skutki starzenia się dla rynku pracy i finansów publicznych", "Kurczenie się zasobu siły roboczej i jego starzenie (niższa mobilność, inna produktywność), niedobory pracowników, rosnąca rola automatyzacji i imigracji; wyższe wydatki na emerytury, ochronę zdrowia i opiekę długoterminową przy wolniej rosnących wpływach ze składek i podatków; zmiana struktury popytu (więcej usług). Odpowiedzi: wydłużanie aktywności zawodowej, aktywizacja kobiet i osób 50+, imigracja, wzrost produktywności.", {"p": "Gdy co roku na emeryturę przechodzi 500 tys. osób, a na rynek pracy wchodzi 350 tys. młodych, firmy mają kłopot z naborem, a budżet – coraz większe wydatki na emerytury i zdrowie.", "k": ["skutki starzenia", "skutków starzenia", "niedobor pracownik", "aktywizacj osób starszych", "aktywności zawodowej osób", "50+"]}),
 ("Opieka długoterminowa", "Wsparcie osób niesamodzielnych (z powodu wieku, choroby, niepełnosprawności) w codziennym funkcjonowaniu – opieka domowa, środowiskowa, instytucjonalna (zakłady opiekuńczo-lecznicze, domy pomocy społecznej); wraz ze starzeniem się rośnie popyt na nią, a maleje potencjał opieki rodzinnej (luka opiekuńcza). W Polsce brak odrębnego ubezpieczenia pielęgnacyjnego. Głównym źródłem niesamodzielności w starości jest demencja (w 2021 r. ok. 57 mln chorych na świecie według WHO, w 60–70% choroba Alzheimera); Goodhart i Pradhan przewidują „kryzys opieki” – rosnący popyt na pracowników opieki przy kurczących się zasobach pracy podniesie jej koszty.", {"p": "Osiemdziesięciolatek po udarze potrzebuje pomocy w ubieraniu się i myciu; jeśli nie ma rodziny na miejscu, potrzebna jest opiekunka lub dom opieki – to opieka długoterminowa.", "k": ["opiek długoterminow", "opieka długoterminowa", "opieki długoterminowej", "luka opiekuńcz", "niesamodzieln", "demencj", "alzheimer"]}),
 ("Polityka senioralna", "Działania na rzecz poprawy jakości życia osób starszych: aktywność obywatelska i społeczna (rady seniorów, Uniwersytety Trzeciego Wieku), integracja, opieka, zdrowie (geriatria), dostępność (Ogólnopolska Karta Seniora); ustawa o osobach starszych z 2015 r. nakłada obowiązek corocznej informacji o sytuacji osób starszych. Koncepcja aktywnego starzenia się (WHO).", {"p": "Gmina otwiera dzienny dom seniora, Uniwersytet Trzeciego Wieku organizuje zajęcia, a autobusy są niskopodłogowe – polityka senioralna pomaga starszym zachować aktywność i samodzielność.", "k": ["polityk senioraln", "polityka senioralna", "polityki senioralnej", "aktywn starzen", "uniwersytet trzeciego wieku", "rady seniorów"]}),
 ("Transfery międzypokoleniowe i rachunkowość pokoleniowa", "Przepływy zasobów między pokoleniami: prywatne (w rodzinie – utrzymanie dzieci, opieka nad rodzicami, spadki) i publiczne (emerytury, edukacja, ochrona zdrowia). Rachunkowość pokoleniowa (A. Auerbach, J. Gokhale, L. Kotlikoff, 1991) szacuje obciążenie podatkowe netto obecnych i przyszłych pokoleń wynikające z polityki fiskalnej; sprawiedliwość międzypokoleniowa.", {"p": "Rodzice utrzymują dzieci, pracujący płacą składki na emerytury dziadków, a dziadkowie opiekują się wnukami – pieniądze i czas płyną między pokoleniami w obie strony.", "k": ["transfer międzypokoleniow", "transfery międzypokoleniowe", "rachunkowoś pokoleniow", "rachunkowość pokoleniowa", "kotlikoff", "międzypokoleniow"]}),
 # --- emerytury (Barr, Diamond) ---
 ("Cele systemu emerytalnego (Barr i Diamond)", "Dla jednostek: wygładzanie konsumpcji w cyklu życia (por. Hipoteza cyklu życia) i ubezpieczenie od ryzyka długowieczności; dla państwa: ograniczanie ubóstwa osób starszych i redystrybucja. Kluczowa teza Barra: „produkcja jest najważniejsza” – emerytury, niezależnie od sposobu finansowania, są roszczeniem do przyszłej produkcji, więc problem starzenia rozwiązuje przede wszystkim wzrost produkcji (zatrudnienia i produktywności).", {"p": "System emerytalny to jednocześnie „skarbonka” (przesuwa dochód z młodości na starość), ubezpieczenie (gdy żyjesz dłużej, niż sądziłeś) i walka z ubóstwem najstarszych.", "k": ["cel systemu emerytaln", "cele systemu emerytalnego", "barr", "produkcja jest najważniejsz"]}),
 ("System repartycyjny (PAYG) a kapitałowy", "Repartycyjny (pay-as-you-go) – bieżące składki pracujących finansują bieżące emerytury (umowa międzypokoleniowa), wrażliwy na zmiany demograficzne; kapitałowy (funded) – składki są inwestowane, a emerytura pochodzi z zgromadzonych aktywów, wrażliwy na ryzyko rynkowe i inflację. Przejście z PAYG na system kapitałowy rodzi problem „podwójnego obciążenia” pokolenia przejściowego (finansuje emerytury bieżące i oszczędza na własne).", {"p": "W repartycji twoja dzisiejsza składka płaci emeryturę twojej babci; w systemie kapitałowym trafia na twoje konto inwestycyjne, z którego dostaniesz emeryturę za 40 lat.", "k": ["repartycyjn", "payg", "pay-as-you-go", "kapitałow system emerytaln", "podwójn obciążeni", "umowa międzypokoleniow"]}),
 ("DB, DC i NDC – formuły emerytalne", "DB (defined benefit) – zdefiniowane świadczenie: emerytura zależy od stażu i zarobków (ryzyko ponosi płatnik); DC (defined contribution) – zdefiniowana składka: emerytura zależy od zgromadzonego kapitału (ryzyko ponosi ubezpieczony); NDC (notional defined contribution) – nominalna (wirtualna) zdefiniowana składka: składki są zapisywane i waloryzowane na indywidualnym koncie, ale finansowanie pozostaje repartycyjne. NDC stosują m.in. Włochy (ustawa 1995), Łotwa (1996), Szwecja i Polska (1999).", {"p": "DB: „dostaniesz 60% ostatniej pensji”; DC: „dostaniesz tyle, ile uzbierasz z zysków z inwestycji”; NDC (Polska): „dostaniesz tyle, ile wpłaciłeś, z waloryzacją, podzielone przez lata życia na emeryturze”.", "k": ["zdefiniowan świadczeni", "zdefiniowane świadczenie", "zdefiniowanego świadczenia", "zdefiniowan składk", "zdefiniowana składka", "zdefiniowanej składce", "ndc", "nominaln zdefiniowan", "db", "dc"]}),
 ("Obliczanie emerytury w polskim systemie", "Emerytura z ZUS = podstawa (zwaloryzowane składki na koncie i subkoncie + zwaloryzowany kapitał początkowy za okres przed 1999 r.) podzielona przez średnie dalsze trwanie życia w wieku przejścia na emeryturę (w miesiącach) z tablic GUS. Wyższy wiek przejścia ⇒ większy kapitał i krótsze dalsze trwanie życia ⇒ wyższa emerytura.", {"w": "E = (składki + kapitał początkowy) / średnie dalsze trwanie życia (mies.)", "p": "Kapitał 600 000 zł, dalsze trwanie życia 260 mies. ⇒ E ≈ 2308 zł brutto.", "k": ["kapitał początkow", "obliczani emerytur", "wysokoś emerytur", "wysokość emerytury"]}),
 ("Waloryzacja i emerytura minimalna", "Waloryzacja – coroczne (od 1 marca) podwyższenie emerytur i rent wskaźnikiem równym inflacji emeryckiej powiększonej o co najmniej 20% realnego wzrostu przeciętnego wynagrodzenia; waloryzacja składek na kontach – według wzrostu funduszu płac. Emerytura minimalna – gwarantowana przy stażu 20 lat (kobiety) i 25 lat (mężczyźni). Trzynasta emerytura (od 2019 r.) i czternasta (od 2021 r.) – dodatkowe roczne świadczenia.", {"p": "Gdy ceny rosną o 5%, a płace realnie o 3%, emerytury rosną co najmniej o 5% plus 20% z 3%, czyli o ok. 5,6% – tak nie tracą siły nabywczej.", "u": "Od 1 marca 2026 r.: wskaźnik waloryzacji 105,3%, emerytura minimalna 1978,50 zł brutto.", "k": ["waloryzacj emerytur", "emerytur minimaln", "emerytura minimalna", "najniższ emerytur", "trzynast emerytur", "czternast emerytur"]}),
 ("Ryzyko długowieczności i renta dożywotnia", "Ryzyko, że oszczędności nie wystarczą, bo człowiek żyje dłużej, niż przewidywał. Ubezpieczają od niego renta dożywotnia (annuity – wypłaty do końca życia za jednorazową składkę) oraz publiczne systemy emerytalne; rynek prywatnych rent jest słaby z powodu negatywnej selekcji i niepewności co do przyszłej długości życia całych roczników.", {"p": "Emerytka zaplanowała oszczędności na 15 lat, a żyje 25 – bez renty dożywotniej (jak emerytura z ZUS) zabrakłoby jej pieniędzy na ostatnie 10 lat.", "k": ["długowieczn", "rent dożywotn", "renta dożywotnia", "annuit"]}),
 ("Warunek Aarona (paradoks Aarona–Samuelsona)", "System repartycyjny daje wyższą stopę zwrotu niż kapitałowy, gdy suma tempa wzrostu ludności (n) i płac realnych (g) przewyższa realną stopę procentową (r) (H. Aaron 1966, na podstawie modelu pokoleń nakładających się P. Samuelsona z 1958 r.). Starzenie się (n < 0) osłabia ten argument.", {"p": "Gdy liczba pracujących maleje o 1% rocznie, a płace rosną o 2%, repartycja „daje” ok. 1% rocznie; jeśli obligacje i akcje dają realnie 3%, korzystniejszy byłby system kapitałowy.", "w": "PAYG korzystniejszy ⇔ n + g > r", "k": ["aaron", "nakładając pokoleń", "pokoleń nakładających"]}),
 ("Mity reform emerytalnych", "Barr i Diamond krytykują m.in. przekonania, że: system kapitałowy sam rozwiązuje problem starzenia (bez wzrostu produkcji – nie), że prywatyzacja zwiększa oszczędności narodowe automatycznie, że przejście na system kapitałowy jest bezkosztowe, że zobowiązania PAYG to „ukryty dług” równoważny długowi publicznemu, że indywidualne konta zawsze przynoszą wyższe emerytury (koszty zarządzania obniżają świadczenia). Rozwiązania: późniejszy wiek emerytalny powiązany z długością życia, dobrze zaprojektowane mechanizmy automatycznej stabilizacji.", {"p": "Przejście na system kapitałowy samo nie rozwiąże problemu starzenia: emerytury i tak trzeba będzie kupić za dobra wytworzone przez przyszłych pracujących.", "k": ["mit reform", "mity reform", "ukryt dług", "ukryty dług", "automatyczn stabiliz"]}),
 ("Wiek emerytalny a długość życia", "Podnoszenie i zrównywanie wieku emerytalnego to główna odpowiedź na starzenie się: w Polsce ustawa z 2012 r. przewidywała od 2013 r. stopniowe podnoszenie do 67 lat dla obu płci, cofnięte od 1 października 2017 r. (por. Wiek emerytalny w Polsce). Część krajów wiąże wiek emerytalny z oczekiwaną długością życia (np. Dania, Finlandia, Holandia).", {"p": "Gdy wiek emerytalny wynosi 65 lat, a życie wydłuża się o 2 lata, przy tej samej emeryturze system musi wypłacać ją 2 lata dłużej – dlatego niektóre kraje wiążą wiek emerytalny z długością życia.", "k": ["podnoszeni wieku emerytaln", "podwyższeni wieku emerytaln", "67 lat", "zrównani wieku"]}),
 # --- migracje ---
 ("Migracja zarobkowa (ekonomiczna)", "Przemieszczanie się osób w celu podjęcia pracy i uzyskania wyższych dochodów; może być stała, czasowa, sezonowa lub cyrkulacyjna. Migrant zarobkowy wg ONZ – osoba wykonująca pracę w kraju, którego nie jest obywatelem. Typy migracji – zob. tabela działu.", {"p": "Pielęgniarka z Polski wyjeżdża do Niemiec, bo zarobi tam dwa razy więcej – to migracja zarobkowa; jej zarobki częściowo wracają do kraju jako przekazy dla rodziny.", "k": ["migracj zarobkow", "migracja zarobkowa", "migracje zarobkowe", "migracji zarobkowych", "migrant zarobkow", "pracownik sezonow", "migracj sezonow", "migracj cyrkulacyjn", "wahadłow"]}),
 ("Teoria czynników wypychających i przyciągających (push–pull)", "E. Lee (1966), rozwijając „prawa migracji” E.G. Ravensteina (1885): decyzja o migracji wynika z czynników wypychających w kraju pochodzenia (bezrobocie, niskie płace, ubóstwo, konflikty), przyciągających w kraju docelowym (wyższe płace, popyt na pracę, bezpieczeństwo), przeszkód pośrednich (odległość, koszty, przepisy) i cech osobistych.", {"p": "Bezrobocie i niskie płace w rodzinnym mieście „wypychają”, a wolne miejsca pracy i wyższe płace za granicą „przyciągają”; odległość, język i koszty przeprowadzki to przeszkody pośrednie.", "k": ["push", "wypychając", "przyciągając", "ravenstein", "praw migracji"]}),
 ("Neoklasyczna teoria migracji", "Migracje wynikają z międzynarodowych różnic płac i popytu na pracę (makro) oraz z indywidualnego rachunku kosztów i korzyści – migracja jako inwestycja w kapitał ludzki (L. Sjaastad 1962, M. Todaro 1969 – liczy się oczekiwany dochód z uwzględnieniem ryzyka bezrobocia); prowadzą do wyrównywania płac.", {"p": "Gdy hydraulik zarabia w Londynie 3 razy więcej niż w Warszawie, część hydraulików wyjeżdża; w Polsce brakuje ich więc płace rosną, a w Londynie płace rosną wolniej – różnica się zmniejsza.", "k": ["neoklasyczn teori migrac", "todaro", "sjaastad"]}),
 ("Nowa ekonomia migracji zarobkowych", "O. Stark i D. Bloom (1985): decyzję o migracji podejmuje rodzina (gospodarstwo domowe), a nie jednostka – by zdywersyfikować ryzyko dochodowe, pokonać brak kredytu i ubezpieczeń oraz poprawić pozycję względem sąsiadów (deprywacja względna); stąd przekazy pieniężne i migracje czasowe.", {"p": "Rodzina rolnicza wysyła syna do pracy w Holandii nie dlatego, że jest biedna, ale żeby mieć drugie źródło dochodu na wypadek nieurodzaju – migracja jest jak ubezpieczenie.", "k": ["nowa ekonomia migrac", "nowej ekonomii migrac", "stark", "deprywacj względn"]}),
 ("Teorie rynku dualnego, systemów światowych i sieci migracyjnych", "Rynek dualny (M. Piore 1979): gospodarki rozwinięte stale potrzebują imigrantów do prac w sektorze wtórnym (niskopłatnych, niestabilnych, nieprestiżowych), których unikają krajowcy. Systemów światowych (I. Wallerstein): migracje są skutkiem przenikania kapitalizmu z centrum na peryferie. Sieci migracyjne (D. Massey): więzi z wcześniejszymi migrantami obniżają koszty i ryzyko, więc migracje same się podtrzymują (kumulatywna przyczynowość).", {"p": "Do pracy przy zbiorach w Niemczech jedzie się tam, gdzie pracuje już kuzyn: pomoże znaleźć pracę i mieszkanie – sieć znajomych obniża koszty i ryzyko migracji.", "k": ["rynku dualn", "rynek dualn", "rynek pracy dualn", "piore", "systemów światowych", "wallerstein", "sieci migracyjn", "massey", "kumulatywn"]}),
 ("Skutki migracji dla krajów pochodzenia i przyjmujących", "Kraj przyjmujący: uzupełnienie niedoborów pracy, młodsza struktura wieku, wpływy podatkowe i składkowe, ale też koszty integracji i presja na niektóre płace. Kraj pochodzenia: mniejsze bezrobocie, przekazy pieniężne, transfer wiedzy przez powracających, ale drenaż mózgów (por.), ubytek siły roboczej, starzenie się i depopulacja, rodziny rozłączone (eurosieroty).", {"p": "Po 2004 r. w Polsce spadło bezrobocie, a rodziny dostawały przekazy z Wysp; ale brakowało budowlańców i lekarzy, a do systemu emerytalnego wpływało mniej składek.", "k": ["skutk migrac", "skutki migracji", "konsekwencj migrac", "eurosierot", "korzyści z migrac", "kosztów migrac"]}),
 ("Przekazy pieniężne migrantów (remittances)", "Środki przesyłane przez migrantów rodzinom w kraju pochodzenia; w bilansie płatniczym – dochody wtórne (transfery osobiste) lub pierwotne (wynagrodzenia pracowników krótkookresowych). Dla wielu krajów rozwijających się są większe niż pomoc rozwojowa; w Polsce największe po 2004 r.", {"p": "Ukrainka pracująca w Polsce co miesiąc wysyła rodzinie 1000 zł – w bilansie płatniczym Ukrainy to wpływ w dochodach wtórnych, a dla rodziny – pieniądze na szkołę dzieci.", "k": ["przekaz pieniężn", "przekazy pieniężne", "przekazów pieniężnych", "remittance", "transfery osobist"]}),
 ("Cyrkulacja mózgów i migracje powrotne", "Cyrkulacja mózgów (brain circulation) – wielokrotne przemieszczanie się wykwalifikowanych pracowników między krajami z korzyścią dla obu stron (transfer wiedzy, sieci kontaktów); brain waste – praca migrantów poniżej kwalifikacji; brain gain – zysk kraju przyjmującego. Migracje powrotne wspierają programy reemigracyjne.", {"p": "Informatyczka po 8 latach w Dublinie wraca do Krakowa i zakłada firmę z kontaktami z Irlandii – kraj odzyskuje nie tylko pracownika, lecz także wiedzę i sieć kontaktów.", "k": ["cyrkulacj mózgów", "brain circulation", "brain waste", "brain gain", "migracj powrotn", "powrotów", "reemigrac"]}),
 ("Uchodźcy i ochrona międzynarodowa", "Uchodźca (konwencja genewska 1951) – osoba, która z uzasadnionej obawy przed prześladowaniem przebywa poza krajem pochodzenia; inne formy ochrony: ochrona uzupełniająca, azyl, ochrona czasowa (dyrektywa 2001/55/WE – po raz pierwszy uruchomiona w 2022 r. wobec osób uciekających z Ukrainy). Polska przyjęła w 2022 r. największą grupę uchodźców z Ukrainy w UE w pierwszych miesiącach wojny.", {"p": "Dziennikarz prześladowany za poglądy prosi o azyl w Polsce – może uzyskać status uchodźcy. Ktoś, kto szuka lepiej płatnej pracy, jest migrantem zarobkowym, nie uchodźcą.", "k": ["uchodźc", "ochron międzynarodow", "ochrona czasowa", "ochrony czasowej", "azyl", "konwencj genewsk"]}),
 ("Przepisy dotyczące pracy cudzoziemców w Polsce", "Ustawa z 20 marca 2025 r. o warunkach dopuszczalności powierzania pracy cudzoziemcom (od 1 czerwca 2025 r.): zezwolenia na pracę, zezwolenia na pracę sezonową, oświadczenia o powierzeniu pracy (dla obywateli Armenii, Białorusi, Gruzji, Mołdawii i Ukrainy), pełna cyfryzacja (praca.gov.pl), zniesienie testu rynku pracy. Zezwolenie na pobyt czasowy i pracę wydaje wojewoda; sprawy pobytowe nadzoruje Urząd do Spraw Cudzoziemców. Specustawa o pomocy obywatelom Ukrainy (12 marca 2022 r.) wygaszona 4 marca 2026 r.; ochrona czasowa (PESEL UKR) trwa do 4 marca 2027 r., z możliwością uzyskania karty pobytu CUKR.", {"p": "Firma z Poznania chce zatrudnić spawacza z Gruzji – musi uzyskać zezwolenie na pracę albo (dla kilku państw) złożyć oświadczenie o powierzeniu pracy, a pracownik potrzebuje prawa pobytu.", "u": "stan na 2026 r.", "k": ["zezwoleni na pracę", "zezwolenie na pracę", "oświadczeni o powierzeniu", "oświadczenie o powierzeniu", "test rynku pracy", "specustaw", "cukr", "pesel ukr", "urząd do spraw cudzoziemców", "udsc", "cudzoziem"]}),
 ("Karta Polaka i Niebieska Karta UE", "Karta Polaka (ustawa z 7 września 2007 r.) potwierdza przynależność do Narodu Polskiego osób polskiego pochodzenia z zagranicy; daje m.in. prawo do pracy bez zezwolenia i ułatwienia w uzyskaniu pobytu stałego i obywatelstwa. Niebieska Karta UE (dyrektywa 2009/50/WE, zmieniona dyrektywą 2021/1883) – zezwolenie na pobyt i pracę wysoko wykwalifikowanych obywateli państw trzecich.", {"p": "Wnuczka Polaków z Kazachstanu dostaje Kartę Polaka i może pracować w Polsce bez zezwolenia; inżynier z Indii z dobrą ofertą pracy może dostać Niebieską Kartę UE.", "k": ["karta polaka", "karty polaka", "niebiesk kart", "niebieska karta", "blue card"]}),
 ("Swobodny przepływ pracowników w UE i emigracja z Polski po 2004 r.", "Swoboda przepływu osób to jedna z czterech swobód rynku wewnętrznego. Po akcesji rynki pracy od 1 maja 2004 r. otworzyły Wielka Brytania, Irlandia i Szwecja, ostatnie – Niemcy i Austria – 1 maja 2011 r. (okresy przejściowe 2+3+2 lata). Liczba Polaków czasowo przebywających za granicą wzrosła do ponad 2 mln (szczyt ok. 2,5 mln w 2017 r. wg GUS); główne kierunki: Wielka Brytania, Niemcy, Holandia, Irlandia, Norwegia.", {"p": "Po 1 maja 2004 r. student z Lublina mógł legalnie pracować w Londynie bez pozwolenia na pracę – Wielka Brytania od razu otworzyła swój rynek.", "k": ["swobod przepływu pracowników", "swobodny przepływ pracowników", "swobody przepływu osób", "emigracj z polski", "emigracja z polski", "emigracji zarobkowej", "okres przejściow"]}),
 ("Polska jako kraj imigracji", "Od połowy lat 2010. Polska ma dodatnie saldo migracji zagranicznej; od 2017 r. przez kilka lat wydawała najwięcej w UE pierwszych zezwoleń na pobyt w celu pracy. Cudzoziemcy ubezpieczeni w ZUS: ok. 1,29 mln (grudzień 2025 r., 7,9% ubezpieczonych) – głównie obywatele Ukrainy, Białorusi i Gruzji.", {"p": "W wielu polskich miastach kierowcami, magazynierami i pracownikami budów są dziś Ukraińcy, Białorusini czy Kolumbijczycy – ponad milion cudzoziemców płaci składki w ZUS.", "u": "stan na koniec 2025 r.", "k": ["kraj imigrac", "kraju imigrac", "imigracj do polski", "imigranci w polsce", "cudzoziemcy w zus", "cudzoziemców w zus"]}),
 ("Polityka migracyjna i integracja imigrantów", "Polityka migracyjna – zasady wjazdu, pobytu, pracy, naturalizacji i integracji cudzoziemców oraz wspierania powrotów obywateli; modele integracji: asymilacyjny, wielokulturowy, integracyjny (prawa i obowiązki obu stron). Strategia migracyjna Polski na lata 2025–2030 „Odzyskać kontrolę. Zapewnić bezpieczeństwo” (przyjęta w październiku 2024 r.) akcentuje kontrolę napływu i bezpieczeństwo.", {"p": "Dzieci imigrantów, które szybko uczą się polskiego w szkole, a ich rodzice mają legalną pracę i kursy językowe, łatwiej się integrują – to cel polityki integracyjnej.", "k": ["polityk migracyjn", "polityka migracyjna", "polityki migracyjnej", "integracj imigrant", "integracja imigrantów", "asymilac", "wielokulturow", "strategi migracyjn"]}),
 ("Międzynarodowe instytucje ds. migracji", "IOM – Międzynarodowa Organizacja ds. Migracji (od 1951 r., od 2016 r. agencja powiązana z ONZ, siedziba Genewa); UNHCR – Wysoki Komisarz ONZ ds. Uchodźców (od 1950 r.); Frontex – Europejska Agencja Straży Granicznej i Przybrzeżnej (Warszawa, od 2005 r.); EUAA – Agencja UE ds. Azylu.", {"k": ["iom", "unhcr", "frontex", "euaa"]}),
 ("Siatka Lexisa (siatka demograficzna)", "Wykres do analizy zdarzeń demograficznych (W. Lexis, 1875): na osi poziomej czas kalendarzowy, na pionowej wiek. Życie każdej osoby to odcinek pod kątem 45°, a cała generacja (kohorta urodzeń) – pas równoległych linii. Pozwala rozróżnić trzy ujęcia: wiek, okres (rok kalendarzowy) i kohortę (rok urodzenia); ponieważ kohorta = okres − wiek, dowolne dwa wyznaczają trzecie.", {"p": "Na siatce Lexisa każdy rocznik to ukośna linia: urodzeni w 2000 r. w 2025 r. mają 25 lat – można śledzić, co działo się z jedną kohortą przez całe jej życie.", "k": ["siatk lexisa", "siatka lexisa", "siatce lexisa", "diagram lexisa", "siatk demograficzn", "siatka demograficzna"]}),
 ("Kohorta (generacja) i analiza kohortowa", "Kohorta – grupa osób, które w tym samym okresie przeżyły to samo zdarzenie początkowe (np. urodziły się w danym roku – generacja, zawarły małżeństwo – kohorta małżeństw). Analiza kohortowa (wzdłużna) śledzi jedną kohortę przez całe życie; analiza przekrojowa (okresowa) opisuje wiele kohort w jednym roku. Miary okresowe, np. roczny TFR, zaniżają dzietność, gdy rośnie wiek rodzenia dzieci (efekt tempa, Bongaarts i Feeney).", {"p": "Kobiety urodzone w 1975 r. to jedna kohorta – znając liczbę dzieci, które urodziły do 50. roku życia, znamy ich ostateczną dzietność.", "k": ["kohort", "generacj urodzeń", "analiz kohortow", "analiza kohortowa", "analiz przekrojow", "efekt tempa", "efektu tempa"]}),
 ("Standaryzacja współczynników demograficznych", "Sposób porównywania współczynników (np. zgonów) populacji o różnej strukturze wieku. Surowy współczynnik zgonów zależy od udziału osób starszych, więc starsza populacja wypada gorzej nawet przy tym samym ryzyku w każdym wieku. Standaryzacja bezpośrednia stosuje cząstkowe współczynniki badanych populacji do jednej populacji standardowej; pośrednia – współczynniki standardowe do struktury badanej populacji i porównuje zgony faktyczne z oczekiwanymi (SMR).", {"p": "Floryda ma wyższy surowy współczynnik zgonów niż Alaska, bo mieszka tam wielu emerytów – po standaryzacji na tę samą strukturę wieku różnica może zniknąć.", "k": ["standaryzacj", "współczynnik standaryzowan", "współczynniki standaryzowane", "surow współczynnik", "surowy współczynnik", "smr"]}),
 ("Małżeńskość i rozwodowość", "Małżeńskość – natężenie zawierania małżeństw, mierzone m.in. współczynnikiem małżeństw na 1 000 ludności i średnim wiekiem przy pierwszym ślubie; rozwodowość – natężenie rozwodów (na 1 000 ludności lub na 100 nowo zawartych małżeństw). W Polsce w 2024 r. zawarto ok. 135 tys. małżeństw (3,6 na 1 000 ludności), a rozwodów było ok. 1,5 na 1 000; spadek małżeńskości i wzrost kohabitacji to przejaw drugiego przejścia demograficznego.", {"p": "Gdy młodzi częściej żyją w związkach nieformalnych i później biorą ślub, spada liczba małżeństw – a w Polsce, gdzie większość dzieci rodzi się w małżeństwie, spada też liczba urodzeń.", "k": ["małżeńskoś", "rozwodowoś", "współczynnik małżeństw", "współczynnika małżeństw", "zawieranie małżeństw", "zawierania małżeństw", "rozwodów"]}),
 ("Gospodarstwo domowe i rodzina – nuklearyzacja", "Gospodarstwo domowe – zespół osób wspólnie mieszkających i utrzymujących się (lub osoba samotna); rodzina – osoby powiązane więzami małżeństwa lub pokrewieństwa (para z dziećmi lub bez, samotny rodzic z dziećmi). Nuklearyzacja – przejście od rodzin wielopokoleniowych do rodzin dwupokoleniowych (nuklearnych); współcześnie maleje przeciętna wielkość gospodarstwa i rośnie udział gospodarstw jednoosobowych, co zwiększa popyt na mieszkania mimo spadku liczby ludności.", {"p": "Kiedyś pod jednym dachem mieszkali dziadkowie, rodzice i dzieci; dziś najczęściej tylko rodzice z dziećmi albo jedna osoba – stąd rosnący popyt na małe mieszkania.", "k": ["nuklearyzacj", "rodzin nuklearn", "rodzina nuklearna", "rodziny nuklearnej", "gospodarstw jednoosobow", "gospodarstwa jednoosobowe", "rodzin wielopokoleniow"]}),
 ("Teoria optimum zaludnienia", "Teoria ludności optymalnej (K. Wicksell, E. Cannan): istnieje liczba ludności, przy której – przy danych zasobach i technice – dochód na mieszkańca jest najwyższy. Gdy przyrost ludności podnosi dochód per capita, kraj jest niedoludniony; gdy go obniża – przeludniony. Krytyka: optimum zmienia się z postępem technicznym, a teoria pomija podział dochodu i inne cele społeczne.", {"p": "Na bezludnej wyspie trzecia osoba pomaga zbudować łódź i dochód na głowę rośnie; tysięczna osoba musi już dzielić się tym samym kawałkiem ziemi – gdzieś pomiędzy jest optimum.", "k": ["optimum zaludnieni", "optimum ludnościow", "ludności optymaln", "ludność optymalna", "optymaln liczb ludności", "niedoludni"]}),
 ("Bliższe determinanty płodności (Davis–Blake, Bongaarts)", "Czynniki biologiczne i behawioralne, przez które działają wszystkie wpływy społeczne i ekonomiczne na liczbę urodzeń. K. Davis i J. Blake (1956) wyróżnili 11 zmiennych pośredniczących; J. Bongaarts (1978) uprościł model – dzietność to płodność potencjalna pomniejszona przez cztery główne czynniki: odsetek osób w związkach (małżeństwa), antykoncepcję, przerywanie ciąży i niepłodność poporodową (karmienie piersią).", {"p": "Wyższe dochody czy edukacja nie wpływają na liczbę dzieci „bezpośrednio” – działają przez późniejsze zawieranie związków, antykoncepcję i karmienie piersią.", "k": ["bliższ determinant", "bliższe determinanty", "determinant płodności", "determinanty płodności", "bongaarts", "davis i blake", "zmienn pośrednicząc"]}),
 ("Kompresja zachorowalności i teorie długowieczności", "Hipoteza kompresji zachorowalności (J. Fries, 1980): jeśli początek chorób przewlekłych i niepełnosprawności przesuwa się na starszy wiek szybciej niż wiek zgonu, okres życia w złym zdrowiu się skraca, a krzywa przeżycia staje się bardziej „prostokątna”. Hipotezy konkurencyjne: ekspansja zachorowalności (E. Gruenberg – dłuższe życie oznacza więcej lat w chorobie) i dynamiczna równowaga (K. Manton). Od odpowiedzi zależą koszty opieki zdrowotnej i długoterminowej w starzejących się społeczeństwach.", {"p": "Jeśli dzięki zdrowemu stylowi życia choroby przewlekłe zaczynają się w wieku 80, a nie 65 lat, ludzie żyją dłużej i krócej chorują – koszty opieki rosną wolniej.", "k": ["kompresj zachorowalnoś", "kompresja zachorowalności", "kompresji zachorowalności", "ekspansj zachorowalnoś", "fries", "prostokątn", "teori długowiecznoś", "teorie długowieczności"]}),
 ("Paradoks ekonomiczno-demograficzny", "Odwrotna zależność między dochodem a dzietnością: bogatsze kraje i (zwykle) zamożniejsze rodziny mają mniej dzieci, wbrew oczekiwaniu Malthusa, że większe środki oznaczają więcej potomstwa. Wyjaśnienia: wyższy koszt alternatywny czasu (zwłaszcza zarobków kobiet), inwestowanie w „jakość” zamiast liczby dzieci (G. Becker), edukacja, emancypacja i zmiana wartości. J.A. Majcherek wskazuje, że dzietność spada nawet przy poprawie warunków życia rodzin i opieki nad dziećmi; w części regionów Europy zależność ostatnio słabnie.", {"p": "Kraje najbogatsze mają najmniej dzieci, a najbiedniejsze – najwięcej, choć „stać je” najmniej: dzieci w bogatych krajach są drogie (czas, edukacja), w biednych – pomagają w pracy.", "k": ["paradoks ekonomiczno-demograficzn", "paradoksu ekonomiczno-demograficzn", "paradoks demograficzno-ekonomiczn", "demo-ekonomiczn", "majcherek"]}),
 ("Pułapka niskiej dzietności", "Hipoteza W. Lutza, V. Skirbekka i M.R. Testy (2006): po spadku dzietności do bardzo niskiego poziomu działają mechanizmy samopodtrzymujące – demograficzny (mniej przyszłych matek, ujemne tempo wzrostu wbudowane w strukturę wieku), socjologiczny (kolejne pokolenia uznają małą rodzinę za ideał) i ekonomiczny (aspiracje rosną szybciej niż oczekiwane dochody – por. hipoteza Easterlina). Wyjście z pułapki jest trudne, dlatego polityka powinna działać zanim dzietność utrwali się na bardzo niskim poziomie.", {"p": "Gdy przez 30 lat rodzi się mało dzieci, kolejne pokolenie rodziców jest mniej liczne, a model rodziny z jednym dzieckiem staje się normą – trudno wtedy odwrócić trend.", "k": ["pułapk niskiej dzietnoś", "pułapka niskiej dzietności", "pułapki niskiej dzietności", "low fertility trap", "lutz"]}),
 ("Populizm ekonomiczny (makroekonomiczny)", "Według R. Dornbuscha i S. Edwardsa (1990) – polityka stawiająca na wzrost i redystrybucję dochodów przy lekceważeniu ryzyka inflacji, finansowania deficytu, ograniczeń zewnętrznych i reakcji podmiotów na działania nierynkowe (podwyżki płac, kontrola cen, wzrost wydatków, przewartościowany kurs). Typowy przebieg: szybkie ożywienie, potem inflacja, stagflacja i załamanie, najbardziej szkodzące grupom, którym miała pomóc. Goodhart i Pradhan wiążą wzrost populizmu z nierównościami wewnątrz krajów w okresie globalizacji.", {"p": "Rząd w starzejącym się kraju obniża wiek emerytalny i podnosi świadczenia przed wyborami, finansując je długiem – krótko poprawia nastroje, długo obciąża budżet.", "k": ["populizm", "populistyczn", "dornbusch"]}),
 ("Udział płac w dochodzie narodowym (labour share)", "Część dochodu narodowego przypadająca na wynagrodzenia pracowników (płace, składki, świadczenia), w odróżnieniu od dochodów kapitału. W gospodarkach rozwiniętych spadał od lat 80. XX w. (OECD, MFW, MOP), co tłumaczy się globalizacją i wzrostem podaży pracy (wejście Chin i Europy Wschodniej), automatyzacją oraz słabnącą siłą przetargową pracowników; według Goodharta i Pradhana kurczące się zasoby pracy odwrócą ten trend.", {"p": "Gdy brakuje pracowników, firmy muszą płacić więcej – większa część dochodu trafia do pracowników jako płace, a mniejsza do właścicieli kapitału jako zyski.", "k": ["udział płac", "udziału płac", "udział pracy w dochodzie", "udziału pracy w dochodzie", "labour share", "labor share"]}),
 ("Krzywa słonia (Lakner, Milanović)", "Wykres wzrostu dochodów realnych w latach 1988–2008 według percentyli światowego rozkładu dochodów (C. Lakner, B. Milanović, 2013): najszybciej rosły dochody globalnej klasy średniej (głównie Chiny i Azja) i najbogatszego 1%, a najwolniej – grup koło 80.–90. percentyla, czyli niższej klasy średniej krajów bogatych. Kształt przypomina słonia z uniesioną trąbą; ilustruje zwycięzców i przegranych globalizacji.", {"p": "W latach 1988–2008 szybko bogaciła się klasa średnia w Chinach i najbogatsi na świecie, a stali w miejscu robotnicy w krajach rozwiniętych – wykres wygląda jak słoń z uniesioną trąbą.", "k": ["krzyw słonia", "krzywa słonia", "krzywej słonia", "milanovi", "lakner"]}),
 ("Automatyzacja a starzenie się ludności", "Niedobór pracowników w średnim wieku skłania firmy do automatyzacji i robotyzacji: D. Acemoglu i P. Restrepo (2022) pokazali, że kraje i regiony szybciej starzejące się częściej wdrażają roboty i mają więcej innowacji automatyzacyjnych. Automatyzacja może łagodzić skutki kurczenia się zasobów pracy dla wzrostu (obok aktywizacji zawodowej i imigracji), ale obniża udział płac w branżach łatwych do zautomatyzowania.", {"p": "Fabryka nie może znaleźć młodych spawaczy, więc kupuje roboty spawalnicze – w Japonii i Korei, szybko się starzejących, robotów na pracownika jest najwięcej na świecie.", "k": ["automatyzacj", "robotyzacj", "acemoglu i restrepo"]}),
 ("Globalny nadmiar oszczędności (saving glut)", "Teza B. Bernankego (2005): od końca lat 90. oszczędności na świecie – zwłaszcza w szybko rosnących gospodarkach Azji Wschodniej i krajach naftowych – przewyższały popyt inwestycyjny; nadwyżki napływały do USA, finansując deficyt na rachunku bieżącym i obniżając realne stopy procentowe. W ujęciu Goodharta i Pradhana starzenie się zmniejszy nadwyżkę oszczędności (osoby starsze konsumują oszczędności), co podniesie realne stopy procentowe.", {"p": "Chiny i kraje naftowe oszczędzały tak dużo i kupowały tyle amerykańskich obligacji, że ich rentowność spadła – tani kredyt podsycił boom mieszkaniowy w USA.", "k": ["nadmiar oszczędnoś", "nadmiaru oszczędnoś", "saving glut", "savings glut", "nadwyżk oszczędnoś"]}),
 ("Dynamika długu publicznego (r − g) i pułapka zadłużenia", "Relacja długu do PKB rośnie, gdy stopa procentowa od długu (r) przewyższa nominalne tempo wzrostu gospodarki (g), chyba że państwo osiąga nadwyżkę pierwotną; przy r < g dług można rolować bez podnoszenia podatków (O. Blanchard, 2019). Pułapka zadłużenia: przy wysokim długu wzrost stóp procentowych podnosi koszty obsługi i deficyt, co dalej zwiększa dług – zdaniem Goodharta i Pradhana starzenie się, podnosząc stopy, grozi takim scenariuszem.", {"p": "Dług wynosi 60% PKB, odsetki to 5%, a PKB rośnie nominalnie o 3% – bez nadwyżki pierwotnej relacja długu do PKB rośnie co roku o ok. 1,2 pkt proc.", "w": "Δd ≈ (r − g)/(1 + g) · d − nadwyżka pierwotna", "k": ["r − g", "r-g", "r – g", "pułapk zadłużeni", "pułapka zadłużenia", "pułapki zadłużenia", "dynamik długu", "dynamika długu", "dynamiki długu"]}),
 ("Uprzywilejowanie podatkowe długu (debt bias)", "W większości systemów podatku dochodowego od firm odsetki od długu są kosztem uzyskania przychodu, a zwrot dla akcjonariuszy (dywidendy, zysk) – nie (tarcza podatkowa długu). Zachęca to do nadmiernego zadłużania się zamiast finansowania kapitałem własnym i zwiększa ryzyko finansowe. Rozwiązania: limity odliczania odsetek lub ulga na kapitał własny (np. ACE); Goodhart i Pradhan postulują przejście od finansowania długiem do kapitału.", {"p": "Firma finansuje inwestycję kredytem, bo odsetki obniżają podatek dochodowy, a dywidendy dla akcjonariuszy – nie; podatki zachęcają więc do zadłużania się.", "k": ["debt bias", "uprzywilejowani podatkow długu", "uprzywilejowanie podatkowe długu", "preferencj podatkow dla długu", "odliczani odsetek", "limit odliczania odsetek"]}),
 ("Dominacja fiskalna", "Sytuacja, w której polityka fiskalna (wysokie deficyty i dług) narzuca warunki polityce pieniężnej: bank centralny utrzymuje niskie stopy lub finansuje dług, by nie dopuścić do kryzysu zadłużenia, kosztem kontroli inflacji (T. Sargent, N. Wallace, „Some Unpleasant Monetarist Arithmetic”, 1981). Przeciwieństwo – dominacja monetarna: bank centralny niezależnie kontroluje inflację, a polityka fiskalna dostosowuje się, stabilizując dług. Goodhart i Pradhan przewidują narastający konflikt monetarno-fiskalny.", {"p": "Gdy rząd ma ogromny dług, bank centralny może bać się podnieść stopy, bo koszt obsługi długu by eksplodował – polityka fiskalna „rządzi” wtedy pieniężną.", "k": ["dominacj fiskaln", "dominacja fiskalna", "dominacji fiskalnej", "dominacj monetarn", "fiscal dominance", "sargent i wallace", "konflikt monetarno-fiskaln"]}),
 ("Uzasadnienie przymusu emerytalnego (krótkowzroczność)", "Dlaczego państwo zmusza do oszczędzania na starość: ludzie często oszczędzają za mało z powodu krótkowzroczności (nadmiernej preferencji teraźniejszości), braku informacji i trudności decyzji; bez przymusu część osób liczyłaby na pomoc państwa w starości (pokusa nadużycia – „gapowicze” pomocy społecznej). Rynek nie oferuje też w pełni ubezpieczeń od inflacji i długowieczności. Barr i Diamond uznają przymus za uzasadniony, ale wskazują, że jego zakres zależy od zdolności administracyjnych państwa.", {"p": "Dwudziestolatek woli wydać pieniądze dziś niż odkładać na emeryturę za 45 lat; przymus składki chroni go przed własną krótkowzrocznością i społeczeństwo przed kosztami jego ubóstwa.", "k": ["przymus emerytaln", "przymusu emerytaln", "przymus oszczędzani", "przymusowe oszczędzani", "krótkowzrocznoś", "myopi"]}),
 ("Neutralność aktuarialna emerytur", "Zasada, że wartość bieżąca świadczeń zmienia się przy wcześniejszym lub późniejszym przejściu na emeryturę tak, by odpowiadała wartości dodatkowych składek i krótszego okresu pobierania – dalsza praca nie jest wtedy „karana” ani nadmiernie nagradzana. Jeśli emerytura nie rośnie odpowiednio przy odroczeniu, powstaje ukryty podatek od dalszej pracy, który skłania do wcześniejszego odejścia z rynku pracy; reformy obniżają świadczenie za wcześniejszą i podnoszą je za późniejszą emeryturę.", {"p": "Kto przechodzi na emeryturę rok później, dostaje wyższe świadczenie – na tyle wyższe, że łączna suma wypłat (w wartości bieżącej) się nie zmienia; nie ma premii ani kary za wybór.", "k": ["neutralnoś aktuarialn", "neutralność aktuarialna", "neutralności aktuarialnej", "aktuarialnie neutraln", "ukryt podatek od dalszej pracy", "ukryty podatek od dalszej pracy"]}),
 ("Luka emerytalna kobiet (gender pension gap)", "Procentowa różnica między przeciętną (lub medianą) emeryturą mężczyzn i kobiet. W UE w 2024 r. przeciętne emerytury kobiet 65+ były o ok. 24,5% niższe niż mężczyzn (Eurostat). Przyczyny: niższe płace, przerwy na opiekę nad dziećmi i bliskimi, praca w niepełnym wymiarze, krótszy staż, wcześniejszy wiek emerytalny; w systemie zdefiniowanej składki dochodzą dłuższe trwanie życia kobiet. Łagodzą ją m.in. składki za okresy opieki i emerytura minimalna.", {"p": "Kobieta zarabiała mniej, miała przerwy na opiekę nad dziećmi i przeszła na emeryturę 5 lat wcześniej niż mąż – jej emerytura jest o jedną trzecią niższa.", "k": ["luk emerytaln", "luka emerytalna", "luki emerytalnej", "gender pension gap", "emerytur kobiet", "emerytury kobiet"]}),
 ("Bariery migracyjne i dystans", "Czynniki utrudniające migrację mimo różnic dochodów: bariery administracyjnoprawne (wizy, pozwolenia na pracę, uznawanie kwalifikacji, kwoty) oraz dystans – geograficzny (koszty podróży), społeczny (brak sieci znajomych), kulturowy i językowy. W modelach grawitacyjnych przepływy migracyjne rosną z wielkością populacji i różnicą dochodów, a maleją z dystansem; podobieństwo języka i kultury zwiększa migracje.", {"p": "Pensja w Australii może być wyższa niż w Niemczech, ale Polaków jest tam mało – odległość, koszty podróży, wizy i brak znajomych to bariery silniejsze niż różnica płac.", "k": ["barier migracyjn", "bariery migracyjne", "barier w migracjach", "dystans kulturow", "dystans geograficzn", "dystans językow", "model grawitacyjn migracj"]}),
 ("Selekcja migrantów (model Roya–Borjasa)", "Kto wyjeżdża: G. Borjas (1987), opierając się na modelu A.D. Roya, pokazał, że skład migrantów zależy od zwrotu z umiejętności w kraju pochodzenia i docelowym. Z krajów o dużych nierównościach (wysoki zwrot z umiejętności) do krajów bardziej egalitarnych emigrują raczej osoby o niższych kwalifikacjach (selekcja negatywna); z krajów egalitarnych do krajów o dużych nierównościach – osoby o wysokich kwalifikacjach (selekcja pozytywna).", {"p": "Z kraju o małych różnicach płac (np. Szwecji) do USA wyjeżdżają najzdolniejsi, bo tam ich talent jest lepiej opłacany; z kraju o dużych nierównościach wyjeżdżają częściej nisko wykwalifikowani.", "k": ["selekcj migrant", "selekcja migrantów", "selekcji migrantów", "samoselekcj", "borjas", "model roya"]}),
 ("Bilans fiskalny imigracji", "Różnica między podatkami i składkami płaconymi przez imigrantów a otrzymywanymi przez nich świadczeniami i usługami publicznymi. Według OECD (2013, 2021) w większości krajów wpływ imigracji na budżet jest niewielki (bliski zera w relacji do PKB), a przed kryzysem 2008/09 imigranci zwykle wpłacali więcej, niż otrzymywali; kluczowy jest poziom ich zatrudnienia i wiek – młodzi pracujący migranci poprawiają bilans, starzejący się go pogarszają.", {"p": "Młody imigrant, który od razu legalnie pracuje, płaci podatki i składki, a rzadko korzysta ze świadczeń – jego bilans fiskalny jest dodatni; bez prawa do pracy byłby ujemny.", "k": ["bilans fiskaln imigracj", "bilans fiskalny imigracji", "bilansu fiskalnego imigracji", "fiskaln skutk imigracj", "fiskalne skutki imigracji", "wpływ imigracji na budżet"]}),
 ("Kara za macierzyństwo (child penalty)", "Trwały spadek zarobków kobiet po urodzeniu pierwszego dziecka w porównaniu z mężczyznami (H. Kleven, C. Landais, J.E. Søgaard, 2019): w Danii długookresowa luka wynosi ok. 20% i wynika w podobnym stopniu z rzadszej aktywności zawodowej, krótszego czasu pracy i niższych stawek. Wysoki koszt alternatywny macierzyństwa jest jednym z wyjaśnień niskiej dzietności i luki płacowej; łagodzą go m.in. dostęp do żłobków, urlopy dla ojców i elastyczne formy pracy (por. prace C. Goldin, Nobel 2023).", {"p": "Dwoje informatyków zarabia tyle samo do narodzin dziecka; 10 lat później matka zarabia o 30% mniej niż ojciec, bo częściej pracuje na część etatu i rzadziej awansuje.", "k": ["kar za macierzyństw", "kara za macierzyństwo", "kary za macierzyństwo", "child penalty", "child penalties", "kleven"]}),
 # --- uzupełnienie (Plan II, G8): pojęcia potrzebne do pytań o hasło XL ---
 ("Okno demograficzne", "Okres, w którym udział ludności w wieku produkcyjnym jest wyjątkowo wysoki, a obciążenie dziećmi i osobami starszymi – niskie (zwykle kilkadziesiąt lat po spadku dzietności, zanim liczne roczniki przejdą na emeryturę). Otwiera możliwość pierwszej dywidendy demograficznej; w Polsce przypadło mniej więcej na lata 1990–2015.", {"p": "W Polsce w latach 90. i 2000. pracowały jednocześnie liczne roczniki wyżu z lat 50. i echa z lat 80., a dzieci było już mniej – na jednego pracującego przypadało niewiele osób na utrzymaniu.", "k": ["okno demograficzne", "okna demograficznego"]}),
 ("Inercja demograficzna (momentum)", "Tendencja populacji do dalszego wzrostu (albo spadku) przez kilkadziesiąt lat po zmianie dzietności, wynikająca ze struktury wieku: liczne roczniki w wieku rozrodczym dają dużo urodzeń nawet przy dzietności na poziomie zastępowalności (inercja dodatnia), a nieliczne – mało urodzeń nawet po wzroście dzietności (inercja ujemna, np. Polska).", {"p": "Nawet gdyby od jutra każda Polka rodziła średnio 2,1 dziecka, urodzeń byłoby mało, bo w wiek 25–35 lat wchodzą nieliczne roczniki z lat 1990–2010.", "k": ["inercja demograficzna", "momentum demograficzne", "population momentum"]}),
 ("Podwójne starzenie się ludności", "Jednoczesny wzrost udziału osób starszych w całej populacji i udziału najstarszych (80+) wśród osób starszych. Najszybciej rosnąca grupa wieku w Polsce i UE to osoby 80+, które najczęściej potrzebują opieki długoterminowej.", {"p": "Liczba 80-latków w Polsce ma się do 2050 r. mniej więcej podwoić – rośnie więc nie tylko liczba emerytów, lecz także liczba osób niesamodzielnych.", "k": ["podwójne starzenie", "podwójnego starzenia"]}),
 ("Migracja łańcuchowa", "Ciąg migracji, w którym pierwsi migranci ułatwiają wyjazd krewnym i znajomym: informują o pracy, pomagają znaleźć mieszkanie, pożyczają pieniądze. Sieci migracyjne obniżają koszty i ryzyko migracji, dlatego migranci z jednej miejscowości często osiedlają się w tym samym mieście za granicą.", {"p": "Mieszkańcy kilku wsi z Podlasia od dziesięcioleci wyjeżdżają do Brukseli, a górale z Podhala – do Chicago: każdy kolejny jedzie „do swoich”.", "k": ["migracja łańcuchowa", "migracji łańcuchowej", "chain migration"]}),
 ("Efekt tempa i dzietność kohortowa", "Efekt tempa (J. Bongaarts, G. Feeney, 1998) – obniżenie przekrojowego współczynnika dzietności (TFR) wskutek odkładania urodzeń na późniejszy wiek, nawet gdy ostateczna liczba dzieci się nie zmienia. Dzietność kohortowa – przeciętna liczba dzieci urodzonych przez kobiety z danego rocznika do końca wieku rozrodczego; nie zawiera efektu tempa.", {"p": "Gdy kobiety zaczynają rodzić średnio rok później, w okresie przejścia część urodzeń „przesuwa się” na kolejny rok – TFR spada, choć kobiety w końcu urodzą tyle samo dzieci.", "k": ["efekt tempa", "tempo-efekt", "dzietność kohortowa", "dzietności kohortowej"]}),
 ("Współczynnik reprodukcji brutto i netto", "Reprodukcja brutto (GRR) – liczba córek urodzonych przez przeciętną kobietę przy płodności z danego roku (TFR × udział dziewczynek w urodzeniach). Reprodukcja netto (NRR) – liczba córek dożywających wieku matki, czyli GRR skorygowany o umieralność. NRR = 1 oznacza prostą zastępowalność, poniżej 1 – zawężoną reprodukcję.", {"w": "GRR ≈ TFR × 0,487;  NRR = Σ fₓ(dziewczynki) · Lₓ / l₀", "p": "Przy TFR 1,1 współczynnik brutto wynosi ok. 0,53 – na jedną kobietę przypada nieco ponad pół córki, więc pokolenie matek „odtwarza się” w niespełna 55%.", "k": ["współczynnik reprodukcji", "reprodukcja brutto", "reprodukcja netto", "reprodukcji netto", "reprodukcji brutto"]}),
 ("Współczynnik feminizacji i maskulinizacji", "Feminizacja – liczba kobiet na 100 mężczyzn; maskulinizacja – liczba mężczyzn na 100 kobiet (np. wśród noworodków ok. 105–106). W Polsce na 100 mężczyzn przypada ok. 107 kobiet, a wśród osób 80+ – ok. 200 (feminizacja starości wskutek nadumieralności mężczyzn).", {"p": "W domach seniora i na Uniwersytetach Trzeciego Wieku zdecydowanie przeważają kobiety – to skutek tego, że mężczyźni żyją średnio o 7 lat krócej.", "k": ["feminizacja", "feminizacji", "maskulinizacja", "maskulinizacji", "współczynnik płci"]}),
 ("Eksplozja i implozja demograficzna", "Eksplozja demograficzna – gwałtowny wzrost liczby ludności, gdy umieralność już spadła, a rozrodczość pozostaje wysoka (druga faza przejścia demograficznego; np. Afryka Subsaharyjska). Implozja demograficzna – trwały, głęboki ubytek naturalny i szybkie kurczenie się populacji przy bardzo niskiej dzietności.", {"p": "Ludność Nigerii podwaja się w ciągu ok. 30 lat (eksplozja), a ludność Bułgarii od 1989 r. spadła o ok. 30% (implozja wraz z emigracją).", "k": ["eksplozja demograficzna", "eksplozji demograficznej", "implozja demograficzna", "implozji demograficznej"]}),
 ("Pokolenie kanapkowe (sandwich generation)", "Osoby w średnim wieku (zwykle 45–64 lata), które jednocześnie wspierają własne dzieci (lub wnuki) i opiekują się starzejącymi się rodzicami. Obowiązki opiekuńcze spadają głównie na kobiety, co ogranicza ich aktywność zawodową i obniża przyszłe emerytury.", {"p": "Pięćdziesięcioletnia księgowa odbiera po szkole wnuka i codziennie odwiedza chorą matkę – przechodzi na pół etatu, więc mniej zarabia i odkłada mniejszą emeryturę.", "k": ["pokolenie kanapkowe", "pokolenia kanapkowego", "sandwich generation"]}),
 ("Aktywne starzenie się", "Według WHO – proces optymalizacji szans na zdrowie, uczestnictwo i bezpieczeństwo, aby poprawić jakość życia w starszym wieku: dłuższa aktywność zawodowa, udział w życiu społecznym, profilaktyka zdrowotna, uczenie się przez całe życie. Mierzy je Indeks aktywnego starzenia się (Active Ageing Index, UNECE i KE).", {"p": "Emerytowana nauczycielka uczy dzieci imigrantów polskiego jako wolontariuszka, ćwiczy w klubie seniora i dorabia jako korepetytorka – to aktywne starzenie się.", "k": ["aktywne starzenie", "aktywnego starzenia", "active ageing"]}),
 ("Ochrona czasowa (dyrektywa 2001/55/WE)", "Szczególna forma ochrony w UE na wypadek masowego napływu osób przesiedlonych: daje natychmiastowe prawo pobytu, pracy, edukacji i opieki zdrowotnej bez indywidualnych procedur azylowych. Uruchomiona po raz pierwszy w marcu 2022 r. wobec osób uciekających z Ukrainy; w Polsce uzupełniona specustawą z 12 marca 2022 r. (m.in. numer PESEL).", {"p": "Ukrainka, która w marcu 2022 r. przyjechała z dziećmi do Krakowa, mogła po kilku dniach pracować w sklepie, a dzieci – pójść do polskiej szkoły.", "k": ["ochrona czasowa", "ochrony czasowej", "2001/55"]}),
 ("Repatriacja", "Powrót do ojczyzny osób pochodzenia polskiego (lub ich potomków), które z przyczyn historycznych mieszkają za granicą – w Polsce głównie potomków osób deportowanych w głąb ZSRR (np. z Kazachstanu); regulowana ustawą o repatriacji z 2000 r. Repatriant otrzymuje obywatelstwo polskie z mocy prawa po przyjeździe na podstawie wizy krajowej w celu repatriacji.", {"p": "Rodzina z Kazachstanu, której dziadkowie zostali wywiezieni z Kresów w 1936 r., osiedla się w gminie, która zapewnia jej mieszkanie i pracę.", "k": ["repatriacja", "repatriacji", "repatriant"]}),
 ("Gerontechnologia", "Technologie wspierające zdrowie, samodzielność i bezpieczeństwo osób starszych: teleopieka (opaski z przyciskiem alarmowym), czujniki upadku, inteligentne domy, telemedycyna, roboty pomocnicze. Pozwalają dłużej mieszkać we własnym domu (ageing in place) i obniżają koszty opieki instytucjonalnej.", {"p": "Opaska z czujnikiem upadku sama wzywa pomoc, gdy samotnie mieszkający 85-latek przewróci się w nocy – może on dłużej mieszkać u siebie zamiast w domu opieki.", "k": ["gerontechnologia", "gerontechnologii", "teleopieka", "teleopieki"]}),
]
